import * as C from './core.js';
import {conquestView,conquestReward,TERRITORY_TYPES} from './guild-conquest.js';
import {membership,currentId} from './social-core.js';
import {t,localeTag,translateDom} from './i18n.js';
const moves={attack:'Atacar',special:'Romper defesa',repair:'Reparar',fortify:'Fortificar'};
const perks={castle:'Reduz ataques comuns em 20%. Vale 5 pontos por minuto de domínio.',tower:'Reduz ataques comuns em 15%. Vale 3 pontos por minuto de domínio.',house:'Reparos 40% mais eficazes. Vale 2 pontos por minuto de domínio.',cabin:'Sua guilda ganha energia extra nas ordens comuns. Vale 1 ponto por minuto de domínio.'};
export function building(type){const paths={castle:'M12 31V13h8v8h8V10h8v11h8v-8h8v18l-4 5v20H16V36ZM27 56V42a5 5 0 0 1 10 0v14',tower:'M19 56V28l-5-6V10h9v8h6V8h8v10h6v-8h9v12l-5 6v28ZM28 56V43h10v13M29 30h8v6',house:'M10 31 32 10l22 21M16 28v28h32V28M26 56V40h12v16M19 33h5v5M40 33h5v5',cabin:'M8 34 32 13l24 21M16 29v26h32V29M27 55V40h10v15M16 35h32M16 45h11M37 45h11'};return `<svg class="territory-building" viewBox="0 0 64 64" fill="currentColor" fill-opacity=".22" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round" aria-hidden="true"><ellipse cx="32" cy="58" rx="28" ry="4" fill-opacity=".12" stroke="none"/><path d="${paths[type]}"/><path d="M32 10V2l12 3-12 4" fill-opacity=".8"/></svg>`;}
export function createConquestView(env){
 const {escape:esc,button:btn,format:n,assetUrl}=env;let selectedEvent=null,selectedPlace=null,ownRanking=false,busy=false,status='CONNECTING',lastSync=0;
 const tr=value=>esc(t(value)),name=value=>`<span translate="no">${esc(value)}</span>`;
 function selected(){const state=env.getState(),events=(state.social?.events||[]).filter(e=>e.type==='guild-conquest');return conquestView(state,events.find(e=>e.id===selectedEvent)?.id||(events.find(e=>e.enabled&&e.startsAt<=Date.now()&&e.endsAt>Date.now())||events.at(-1))?.id);}
 function render(){const state=env.getState(),view=selected();if(!view)return '';selectedEvent=view.event.id;const event=view.event,own=membership(state),actor=currentId(state),pilot=view.pilots[actor]||{energy:0,used:0},places=Object.values(view.territories),place=view.territories[selectedPlace]||places[0];selectedPlace=place.id;
  const def=TERRITORY_TYPES[place.type],friendly=place.ownerId===own?.guild.id,now=Date.now(),wait=Math.max(0,Math.ceil(((pilot.nextOrderAt||0)-now)/1000)),protection=Math.max(0,Math.ceil((place.protectedUntil-now)/1000)),used=pilot.date===C.dayKey(now)?pilot.used:0,participant=view.contributions[actor],locked=participant&&participant.guildId!==own?.guild.id,robot=state.robots.find(r=>r.uid===state.selectedRobot)||state.robots[0],robotInfo=robot?C.robotInfo(state,robot):null,available=view.phase==='active'&&own&&!locked&&robotInfo?.active&&robotInfo.remainingBattles>0&&!robot?.tradeLock&&!busy&&!wait&&used<event.conquest.dailyOrders;
  const guildName=id=>state.social.guilds.find(g=>g.id===id)?.name||view.ranking.find(p=>p.guildId===id)?.guildName||t('Neutro');const ranks=view.ranking.filter(p=>!ownRanking||p.guildId===own?.guild.id),claimed=state.social.rewardReceipts.some(r=>r.key==='guild-conquest:'+event.id+':'+actor);
  return `<section class="conquest-dashboard" data-conquest-root><header class="conquest-heading"><div><span class="eyebrow">${tr('CONQUISTA DE TERRITÓRIOS')}</span><h2>${name(event.name)}</h2><p>${name(event.description)}</p></div><span class="conquest-sync" role="status">${env.isDemo?tr('Local'):status==='SUBSCRIBED'?tr('Sincronização ao vivo'):tr('Sincronização periódica')}${lastSync?` · ${new Date(lastSync).toLocaleTimeString(localeTag(),{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`:''}</span></header>
  <div class="conquest-event-tabs" ${state.social.events.filter(e=>e.type==='guild-conquest').length===1?'hidden':''}>${state.social.events.filter(e=>e.type==='guild-conquest').map(e=>btn(name(e.name),'conquest-event',`data-id="${esc(e.id)}" aria-pressed="${e.id===event.id}"`,e.id===event.id?'primary':'secondary')).join('')}</div>
  <div class="conquest-summary"><span>${tr({active:'EM DISPUTA',ended:'ENCERRADO',upcoming:'EM BREVE',paused:'PAUSADO'}[view.phase])}</span><span>${tr('Orçamento total')} <b>${n(event.rewardPoolRC)} RC</b></span><span>${tr('Fim')} <b>${new Date(event.endsAt).toLocaleString(localeTag(),{dateStyle:'short',timeStyle:'short'})}</b></span></div>
  <div class="conquest-field"><div class="territory-map" role="group" aria-label="${tr('Mapa de conquista')}" style="--conquest-art:url('${assetUrl(event.scene+'.png')}')">${places.map(p=>{const d=TERRITORY_TYPES[p.type],ours=p.ownerId&&p.ownerId===own?.guild.id;return `<button class="territory-node ${ours?'owned':p.ownerId?'rival':'neutral'} ${p.id===place.id?'selected':''}" data-a="conquest-focus" data-id="${p.id}" aria-pressed="${p.id===place.id}">${building(p.type)}<b>${tr(d.label)} ${p.number}</b><span class="territory-banner">${name(guildName(p.ownerId))}</span><meter min="0" max="${d.health}" value="${p.hp}" aria-label="${tr('Integridade')}"></meter><small>${n(p.hp)} / ${n(d.health)} · ${d.value} ${tr('pts/min')}</small>${p.protectedUntil>now?`<small>${tr('Protegido')}</small>`:p.hp<d.health||p.shield?`<small>${tr('Defesa em alerta')}</small>`:`<small>${tr('Disponível')}</small>`}</button>`;}).join('')}</div>
  <aside class="conquest-command"><h3>${tr(def.label)} ${place.number}</h3><p class="conquest-perk">${tr(perks[place.type])}</p><div class="conquest-vitals"><span>${tr('Integridade')} <b>${place.hp}/${def.health}</b></span><span>${tr('Escudo')} <b>${place.shield}/${Math.floor(def.health*.3)}</b></span><span>${tr('Energia')} <b>${pilot.energy}/4</b></span><span>${tr('Ordens hoje')} <b>${used}/${event.conquest.dailyOrders}</b></span></div>
  <label class="form-field"><span>${tr('Robô')}</span><select id="conquest-robot" ${busy?'disabled':''}>${state.robots.map(r=>`<option value="${esc(r.uid)}" ${r.uid===robot?.uid?'selected':''}>${esc(C.robotInfo(state,r).name)} · ${C.robotInfo(state,r).remainingBattles} ${tr('usos')}</option>`).join('')}</select></label>
  <div class="conquest-orders">${Object.entries(moves).map(([move,label])=>{const offense=['attack','special'].includes(move),disabled=!available||(offense?(friendly||protection>0):!friendly)||(move==='special'&&pilot.energy<3)||(move==='repair'&&(pilot.energy<2||place.hp===def.health))||(move==='fortify'&&place.shield===Math.floor(def.health*.3));return btn(`${tr(label)}<small>${move==='special'?'−3':move==='repair'?'−2':'+1/+2'} ${tr('energia')}</small>`,'conquest-order',`data-id="${place.id}" data-event="${esc(event.id)}" data-move="${move}" data-version="${view.version}" ${disabled?'disabled':''}`,offense?'primary':'secondary');}).join('')}</div>
  <p class="conquest-order-status" role="status">${busy?tr('Enviando ordem…'):!own?tr('Entre em uma guilda para participar.'):locked?tr('Você representa uma única guilda nesta edição.'):wait?`${tr('Próxima ordem em')} ${wait}s`:protection?`${tr('Proteção restante')} ${protection}s`:tr('Cada ordem consome um uso do robô.')}</p>${own?btn(tr('Coordenar no chat'),'guild-chat','','secondary wide'):''}</aside></div>
  <details class="conquest-rules"><summary>${tr('Como conquistar e receber')}</summary><p>${tr('Ataques cooperativos reduzem a defesa. O ataque que esgota a integridade conquista o local para sua guilda. Reparos e escudos ajudam a mantê-lo.')}</p><p>${tr('Vence o maior tempo de domínio ponderado: castelo 5, torre 3, casa 2 e cabana 1 ponto por minuto. Em empate, vale a ordem do identificador da guilda.')}</p><p>${tr('O orçamento é dividido entre os participantes da guilda vencedora proporcionalmente à contribuição. Valores inteiros, arredondados para baixo. Não há prêmio por ataque nem RC além do orçamento.')}</p><p>${tr('Contribuição é o dano ou reparo efetivo. O vínculo à guilda fica fixo nesta edição; o resgate continua disponível após sair.')}</p></details>
  ${view.phase==='ended'&&participant?`<div class="conquest-claim"><b>${tr('Seu prêmio')} · ${n(conquestReward(view,actor))} RC</b>${btn(tr(claimed?'Recompensa recebida':'Resgatar prêmio'),'conquest-claim',`data-id="${esc(event.id)}" ${claimed||busy?'disabled':''}`)}</div>`:''}
  <div class="conquest-boards"><section><h3>${tr('Domínio das guildas')}</h3><ol class="conquest-ranking">${view.guildRanking.map((g,i)=>`<li><b>${i+1}</b><span>${name(guildName(g.guildId))}<small>${g.territories} ${tr('locais')}</small></span><strong>${n(g.control/60000)} ${tr('pontos')}</strong></li>`).join('')||`<li>${tr('Nenhuma contribuição ainda.')}</li>`}</ol></section><section><div class="conquest-ranking-title"><h3>${tr('Ranking dos pilotos')}</h3>${btn(tr(ownRanking?'Todos':'Minha guilda'),'conquest-ranking',`aria-pressed="${ownRanking}" ${!own?'disabled':''}`,'secondary')}</div><ol class="conquest-ranking">${ranks.map((p,i)=>`<li class="${p.userId===actor?'self':''}"><b>${i+1}</b><span>${name(p.name)}<small>${name(p.guildName)} · ${p.captures} ${tr('conquistas')} · ${p.repairs} ${tr('defesa')}</small></span><strong>${n(p.points)}</strong></li>`).join('')||`<li>${tr('Nenhuma contribuição ainda.')}</li>`}</ol></section></div>
  <section class="conquest-history"><h3>${tr('Últimas ordens')}</h3><ol>${view.history.slice(0,12).map(h=>`<li><time>${new Date(h.at).toLocaleTimeString(localeTag(),{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time><span>${name(h.name)} · ${tr(moves[h.move])} · ${tr(TERRITORY_TYPES[view.territories[h.territoryId].type].label)} ${view.territories[h.territoryId].number} <b>+${h.amount}</b>${h.captured?` · <strong>${tr('Conquistado por')} ${name(h.guildName)}</strong>`:''}</span></li>`).join('')||`<li>${tr('Nenhuma contribuição ainda.')}</li>`}</ol></section></section>`;
 }
 function refresh(){const root=document.querySelector('[data-conquest-root]');if(!root||document.hidden)return;const active=document.activeElement;if(active?.tagName==='SELECT'&&root.contains(active))return;const focused=root.contains?.(active)?{action:active.dataset?.a,id:active.dataset?.id,move:active.dataset?.move}:null,open=root.querySelector('details')?.open,top=globalThis.scrollY,scrolls=[...root.querySelectorAll('.conquest-event-tabs,.conquest-ranking,.conquest-history ol')].map(el=>[el.scrollTop,el.scrollLeft]);root.outerHTML=render();const next=document.querySelector('[data-conquest-root]');if(!next)return;const details=next.querySelector('details');if(details)details.open=open;[...next.querySelectorAll('.conquest-event-tabs,.conquest-ranking,.conquest-history ol')].forEach((el,i)=>{if(scrolls[i]){el.scrollTop=scrolls[i][0];el.scrollLeft=scrolls[i][1];}});translateDom(next);if(focused?.action)[...next.querySelectorAll('[data-a]')].find(el=>el.dataset.a===focused.action&&el.dataset.id===focused.id&&el.dataset.move===focused.move)?.focus({preventScroll:true});if(Number.isFinite(top)&&globalThis.scrollY!==top)window.scrollTo({top,behavior:'instant'});}
 return {render,refresh,selected,setEvent:id=>{selectedEvent=id;selectedPlace=null;},focus:id=>{selectedPlace=id;},toggleRanking:()=>{ownRanking=!ownRanking;},setBusy:value=>{busy=value;refresh();},setStatus:value=>{status=value;refresh();},synced:()=>{lastSync=Date.now();refresh();}};
}
